// AI: below section was generated by an AI
// Host test of the certificate date check. The structs mirror the public mbedTLS 3.6 fields the
// firmware reads (mbedtls_x509_time, mbedtls_x509_buf, mbedtls_x509_crt); the firmware build
// instantiates the same templates with the real types.
// Fixture dates come from a throw-away test PKI made with OpenSSL (`openssl x509 -req ... -not_before
// YYYYMMDDhhmmssZ -not_after ...`, read back with `openssl x509 -noout -dates`); no certificate or key is kept.
using namespace KiteWindCert;

#ifndef KITE_TEST_FLOOR
#define KITE_TEST_FLOOR 1767225600 // expected floor without a build epoch: 2026-01-01T00:00:00Z
#endif

struct Time { int year, mon, day, hour, min, sec; };
struct Buf { size_t len; const unsigned char* p; };
struct Crt { Time valid_from, valid_to; Buf subject_raw, issuer_raw; Crt* next; };

static Buf name(const char* text) { return Buf{strlen(text), reinterpret_cast<const unsigned char*>(text)}; }

static const char TEST_ROOT[] = "Kite Test Root CA (throw-away)";
static const Anchor TEST_ANCHOR = {reinterpret_cast<const unsigned char*>(TEST_ROOT), sizeof(TEST_ROOT) - 1, 2082758400}; // 2036-01-01
static const int64_t DEC_2026 = 1796083200; // 2026-12-01T00:00:00Z

static int64_t epoch(Time t) {
  int64_t out = -1;
  assert(mbedtlsTimeToEpoch(t, out));
  return out;
}

static bool invalid(Time t) {
  int64_t out = 12345;
  return !mbedtlsTimeToEpoch(t, out);
}

static void testEpoch() {
  assert(epoch({1970, 1, 1, 0, 0, 0}) == 0);
  assert(epoch({2000, 3, 1, 0, 0, 0}) == 951868800);
  assert(epoch({2000, 2, 29, 0, 0, 0}) == 951782400);   // divisible by 400: leap
  assert(epoch({2024, 2, 29, 12, 0, 0}) == 1709208000); // leap day
  assert(epoch({2026, 1, 1, 0, 0, 0}) == 1767225600);
  assert(epoch({2026, 12, 31, 23, 59, 59}) == 1798761599);
  assert(epoch({2035, 6, 4, 11, 4, 38}) == 2064567878);  // ISRG Root X1 notAfter
  assert(epoch({2038, 1, 19, 3, 14, 8}) == 2147483648);  // one second past 32-bit time_t
  assert(epoch({2100, 2, 28, 23, 59, 59}) == 4107542399);
  assert(epoch({2100, 3, 1, 0, 0, 0}) == 4107542400);     // 2100 is not a leap year
  assert(epoch({1950, 1, 1, 0, 0, 0}) == -631152000);     // earliest UTCTime year
  assert(epoch({9999, 12, 31, 23, 59, 59}) == 253402300799);
  assert(invalid({2100, 2, 29, 0, 0, 0}) && invalid({2023, 2, 29, 0, 0, 0}) && invalid({2026, 4, 31, 0, 0, 0}));
  assert(invalid({2026, 0, 1, 0, 0, 0}) && invalid({2026, 13, 1, 0, 0, 0}) && invalid({2026, 1, 0, 0, 0, 0}));
  assert(invalid({2026, 1, 32, 0, 0, 0}) && invalid({2026, 1, 1, 24, 0, 0}) && invalid({2026, 1, 1, 0, 60, 0}));
  assert(invalid({2026, 1, 1, 0, 0, 60}) && invalid({2026, 1, 1, -1, 0, 0}) && invalid({2026, 1, 1, 0, -1, 0}));
  assert(invalid({2026, 1, 1, 0, 0, -1}) && invalid({0, 1, 1, 0, 0, 0}) && invalid({10000, 1, 1, 0, 0, 0}));
  assert(invalid({2026, -1, 1, 0, 0, 0}) && invalid({2026, 1, -5, 0, 0, 0}));
}

static void testFloor() {
  assert(MIN_VALID_UTC == KITE_TEST_FLOOR);
  assert(MIN_VALID_UTC >= CLOCK_FLOOR_UTC);
  // Fixture leaf valid 2026-11-01 to 2027-02-01; the floor sits below its window in every test build.
  const int64_t from = 1793491200, to = 1801440000;
  assert(certDatesValid(from, to, DEC_2026));
  assert(!certDatesValid(0, INT64_MAX, MIN_VALID_UTC - 1)); // clock before the floor fails closed
  assert(certDatesValid(0, INT64_MAX, MIN_VALID_UTC));
  assert(!certDatesValid(0, INT64_MAX, 0) && !certDatesValid(0, INT64_MAX, -1));
}

static void testDates() {
  const int64_t from = 1793491200, to = 1801440000; // 2026-11-01 .. 2027-02-01
  assert(certDatesValid(from, to, DEC_2026));
  assert(!certDatesValid(1735689600, 1743465600, DEC_2026)); // expired (2025-01-01 .. 2025-04-01)
  assert(!certDatesValid(1893456000, 1901232000, DEC_2026)); // not yet valid (2030-01-01 .. 2030-04-01)
  // RFC 5280 4.1.2.5: both ends inclusive, exact seconds (window above every test floor).
  const int64_t start = 1801440000, end = 1830297600; // 2027-02-01 .. 2028-01-01
  assert(certDatesValid(start, end, start) && !certDatesValid(start, end, start - 1));
  assert(certDatesValid(start, end, end) && !certDatesValid(start, end, end + 1));
  assert(certDatesValid(start, start, start));
  assert(!certDatesValid(to, from, DEC_2026)); // notBefore after notAfter
  // 64-bit arithmetic past 2038 and past the trust anchor end.
  assert(certDatesValid(2147483000, 2147490000, 2147483648));
  assert(certDatesValid(2064567878, 4107542400, 4107542400));
  assert(!certDatesValid(2147483000, 2147490000, 2147490001));
}

// Chain builders: leaf first, linked by next, as mbedtls_ssl_get_peer_cert() returns them.
static Crt cert(Time from, Time to, const char* subject, const char* issuer, Crt* next = nullptr) {
  return Crt{from, to, name(subject), name(issuer), next};
}

static const char INT[] = "Kite Test Intermediate (throw-away)";
static const char LEAF[] = "api.example.test";

static void testChain() {
  Crt intOk = cert({2026, 1, 1, 0, 0, 0}, {2031, 1, 1, 0, 0, 0}, INT, TEST_ROOT);
  Crt intOld = cert({2024, 1, 1, 0, 0, 0}, {2025, 1, 1, 0, 0, 0}, INT, TEST_ROOT);
  Crt intFuture = cert({2027, 1, 1, 0, 0, 0}, {2031, 1, 1, 0, 0, 0}, INT, TEST_ROOT);
  Crt intBad = cert({2026, 2, 30, 0, 0, 0}, {2031, 1, 1, 0, 0, 0}, INT, TEST_ROOT); // unparsable date
  Crt valid = cert({2026, 11, 1, 0, 0, 0}, {2027, 2, 1, 0, 0, 0}, LEAF, INT, &intOk);
  Crt expired = cert({2025, 1, 1, 0, 0, 0}, {2025, 4, 1, 0, 0, 0}, LEAF, INT, &intOk);
  Crt future = cert({2030, 1, 1, 0, 0, 0}, {2030, 4, 1, 0, 0, 0}, LEAF, INT, &intOk);
  Crt underOld = cert({2026, 11, 1, 0, 0, 0}, {2027, 2, 1, 0, 0, 0}, LEAF, INT, &intOld);
  Crt underFuture = cert({2026, 11, 1, 0, 0, 0}, {2027, 2, 1, 0, 0, 0}, LEAF, INT, &intFuture);
  Crt underBad = cert({2026, 11, 1, 0, 0, 0}, {2027, 2, 1, 0, 0, 0}, LEAF, INT, &intBad);
  assert(chainDatesValid(&valid, DEC_2026, TEST_ANCHOR));
  assert(!chainDatesValid(&expired, DEC_2026, TEST_ANCHOR));
  assert(!chainDatesValid(&future, DEC_2026, TEST_ANCHOR));
  assert(!chainDatesValid(&underOld, DEC_2026, TEST_ANCHOR));
  assert(!chainDatesValid(&underFuture, DEC_2026, TEST_ANCHOR));
  assert(!chainDatesValid(&underBad, DEC_2026, TEST_ANCHOR));
  assert(!chainDatesValid(static_cast<const Crt*>(nullptr), DEC_2026, TEST_ANCHOR)); // no peer certificate
  // Clock: unset, before the floor, behind the leaf, ahead of the leaf, past the anchor.
  assert(!chainDatesValid(&valid, 0, TEST_ANCHOR) && !chainDatesValid(&valid, MIN_VALID_UTC - 1, TEST_ANCHOR));
  assert(!chainDatesValid(&valid, 1780272000, TEST_ANCHOR) && !chainDatesValid(&valid, 1830297600, TEST_ANCHOR));
  Crt longLived = cert({2026, 1, 1, 0, 0, 0}, {2040, 1, 1, 0, 0, 0}, LEAF, TEST_ROOT);
  assert(chainDatesValid(&longLived, TEST_ANCHOR.notAfter, TEST_ANCHOR));
  assert(!chainDatesValid(&longLived, TEST_ANCHOR.notAfter + 1, TEST_ANCHOR));

  // An unrelated stale extra certificate is skipped; its successor is still checked.
  Crt intAfterStale = cert({2026, 1, 1, 0, 0, 0}, {2031, 1, 1, 0, 0, 0}, INT, TEST_ROOT);
  Crt stale = cert({2020, 1, 1, 0, 0, 0}, {2021, 1, 1, 0, 0, 0}, "Other", "Elsewhere", &intAfterStale);
  Crt withStale = cert({2026, 11, 1, 0, 0, 0}, {2027, 2, 1, 0, 0, 0}, LEAF, INT, &stale);
  assert(chainDatesValid(&withStale, DEC_2026, TEST_ANCHOR));
  Crt oldAfterStale = cert({2024, 1, 1, 0, 0, 0}, {2025, 1, 1, 0, 0, 0}, INT, TEST_ROOT);
  Crt stale2 = cert({2020, 1, 1, 0, 0, 0}, {2021, 1, 1, 0, 0, 0}, "Other", "Elsewhere", &oldAfterStale);
  Crt withStaleOld = cert({2026, 11, 1, 0, 0, 0}, {2027, 2, 1, 0, 0, 0}, LEAF, INT, &stale2);
  assert(!chainDatesValid(&withStaleOld, DEC_2026, TEST_ANCHOR));

  // Long chain: the walk stops at the certificate the anchor issued, so an expired cross-signed
  // copy of the root behind it does not reject a valid chain.
  Crt crossRoot = cert({2021, 1, 20, 0, 0, 0}, {2024, 9, 30, 18, 14, 3}, TEST_ROOT, "Old Root");
  Crt intLong = cert({2026, 1, 1, 0, 0, 0}, {2031, 1, 1, 0, 0, 0}, INT, TEST_ROOT, &crossRoot);
  Crt leafLong = cert({2026, 11, 1, 0, 0, 0}, {2027, 2, 1, 0, 0, 0}, LEAF, INT, &intLong);
  assert(chainDatesValid(&leafLong, DEC_2026, TEST_ANCHOR));

  // Two-level intermediates (ECDSA style: leaf, intermediate, cross-signed second root).
  Crt second = cert({2026, 1, 1, 0, 0, 0}, {2030, 1, 1, 0, 0, 0}, "Second Root", TEST_ROOT);
  Crt e = cert({2026, 1, 1, 0, 0, 0}, {2029, 1, 1, 0, 0, 0}, "E", "Second Root", &second);
  Crt leafE = cert({2026, 11, 1, 0, 0, 0}, {2027, 2, 1, 0, 0, 0}, LEAF, "E", &e);
  assert(chainDatesValid(&leafE, DEC_2026, TEST_ANCHOR));
  second.valid_to = {2026, 11, 30, 23, 59, 59};
  assert(!chainDatesValid(&leafE, DEC_2026, TEST_ANCHOR));

  // The anchor must be reached within MAX_CHAIN certificates; otherwise fail closed.
  Crt orphanInt = cert({2026, 1, 1, 0, 0, 0}, {2031, 1, 1, 0, 0, 0}, INT, "Unknown Root");
  Crt orphan = cert({2026, 11, 1, 0, 0, 0}, {2027, 2, 1, 0, 0, 0}, LEAF, INT, &orphanInt);
  assert(!chainDatesValid(&orphan, DEC_2026, TEST_ANCHOR));
  Crt leafOnly = cert({2026, 11, 1, 0, 0, 0}, {2027, 2, 1, 0, 0, 0}, LEAF, INT);
  assert(!chainDatesValid(&leafOnly, DEC_2026, TEST_ANCHOR));
  Crt c4 = cert({2026, 1, 1, 0, 0, 0}, {2031, 1, 1, 0, 0, 0}, "C4", TEST_ROOT);
  Crt c3 = cert({2026, 1, 1, 0, 0, 0}, {2031, 1, 1, 0, 0, 0}, "C3", "C4", &c4);
  Crt c2 = cert({2026, 1, 1, 0, 0, 0}, {2031, 1, 1, 0, 0, 0}, "C2", "C3", &c3);
  Crt c1 = cert({2026, 1, 1, 0, 0, 0}, {2031, 1, 1, 0, 0, 0}, "C1", "C2", &c2);
  Crt deep = cert({2026, 11, 1, 0, 0, 0}, {2027, 2, 1, 0, 0, 0}, LEAF, "C1", &c1);
  assert(MAX_CHAIN == 4);
  assert(!chainDatesValid(&deep, DEC_2026, TEST_ANCHOR)); // anchor issuer is the fifth certificate
  assert(chainDatesValid(&c1, DEC_2026, TEST_ANCHOR));    // fourth certificate: within the bound

  // The anchor comparison uses length and bytes.
  Crt prefix = cert({2026, 1, 1, 0, 0, 0}, {2031, 1, 1, 0, 0, 0}, LEAF, "Kite Test Root CA");
  assert(!chainDatesValid(&prefix, DEC_2026, TEST_ANCHOR));
  Crt longer = cert({2026, 1, 1, 0, 0, 0}, {2031, 1, 1, 0, 0, 0}, LEAF, "Kite Test Root CA (throw-away) 2");
  assert(!chainDatesValid(&longer, DEC_2026, TEST_ANCHOR));
  // Same length, different bytes: not the anchor, so the walk does not stop there.
  static_assert(sizeof("Kite Test Root CA (throw-awaz)") == sizeof(TEST_ROOT), "equal-length impostor");
  Crt sameLength = cert({2026, 1, 1, 0, 0, 0}, {2031, 1, 1, 0, 0, 0}, LEAF, "Kite Test Root CA (throw-awaz)");
  assert(!chainDatesValid(&sameLength, DEC_2026, TEST_ANCHOR));
  // Same-length subject with different bytes is not the issuer: the expired impostor is skipped.
  static_assert(sizeof("Kite Test Intermediate (throw-awaz)") == sizeof(INT), "equal-length impostor");
  Crt realInt = cert({2026, 1, 1, 0, 0, 0}, {2031, 1, 1, 0, 0, 0}, INT, TEST_ROOT);
  Crt impostor = cert({2024, 1, 1, 0, 0, 0}, {2025, 1, 1, 0, 0, 0}, "Kite Test Intermediate (throw-awaz)", TEST_ROOT, &realInt);
  Crt leafImpostor = cert({2026, 11, 1, 0, 0, 0}, {2027, 2, 1, 0, 0, 0}, LEAF, INT, &impostor);
  assert(chainDatesValid(&leafImpostor, DEC_2026, TEST_ANCHOR));
}

// The real anchor: a chain shaped like the one api.kustgloed.nl may serve, including the long chain.
static void testIsrgChain() {
  const Anchor isrg = {KiteWindTls::ISRG_ROOT_X1_SUBJECT, KiteWindTls::ISRG_ROOT_X1_SUBJECT_LENGTH, KiteWindTls::ISRG_ROOT_X1_NOT_AFTER_UTC};
  Crt cross = cert({2021, 1, 20, 19, 14, 3}, {2024, 9, 30, 18, 14, 3}, "", "DST Root CA X3");
  cross.subject_raw = Buf{isrg.subjectLength, isrg.subject};
  Crt r = cert({2024, 3, 13, 0, 0, 0}, {2027, 3, 12, 23, 59, 59}, "R", "", &cross);
  r.issuer_raw = Buf{isrg.subjectLength, isrg.subject};
  Crt leaf = cert({2026, 11, 1, 0, 0, 0}, {2027, 1, 30, 0, 0, 0}, "api", "R", &r);
  assert(chainDatesValid(&leaf, DEC_2026, isrg));
  assert(!chainDatesValid(&leaf, 1801440000, isrg)); // leaf expired
  r.next = nullptr;
  assert(chainDatesValid(&leaf, DEC_2026, isrg));    // short chain
  assert(!chainDatesValid(&leaf, isrg.notAfter + 1, isrg));
}

// Recording transport: counts bytes that would reach the peer.
struct RecordingSession {
  size_t bytes = 0;
  unsigned writes = 0;
  size_t write(const uint8_t* data, size_t length) {
    assert(data);
    bytes += length;
    writes++;
    return length;
  }
};

static void testGate() {
  static const uint8_t request[] = "GET /api/v1/led-conditions HTTP/1.1\r\nAuthorization: Bearer test-only\r\n\r\n";
  const size_t length = sizeof(request) - 1;
  Crt intOk = cert({2026, 1, 1, 0, 0, 0}, {2031, 1, 1, 0, 0, 0}, INT, TEST_ROOT);
  Crt valid = cert({2026, 11, 1, 0, 0, 0}, {2027, 2, 1, 0, 0, 0}, LEAF, INT, &intOk);
  Crt expired = cert({2025, 1, 1, 0, 0, 0}, {2025, 4, 1, 0, 0, 0}, LEAF, INT, &intOk);
  Crt future = cert({2030, 1, 1, 0, 0, 0}, {2030, 4, 1, 0, 0, 0}, LEAF, INT, &intOk);

  SessionGate gate;
  RecordingSession peer;
  assert(!gate.admitted() && gate.write(peer, request, length) == 0 && peer.writes == 0); // no handshake yet

  // Rejected peers get no byte.
  const Crt* rejectedChains[] = {&expired, &future, nullptr};
  for (const Crt* chain : rejectedChains) {
    RecordingSession rejected;
    assert(!gate.admit(chain, DEC_2026, TEST_ANCHOR));
    assert(gate.write(rejected, request, length) == 0 && rejected.writes == 0 && rejected.bytes == 0);
  }
  RecordingSession early;
  assert(!gate.admit(&valid, MIN_VALID_UTC - 1, TEST_ANCHOR) && gate.write(early, request, length) == 0 && !early.writes);

  // Valid peer: the existing request goes out unchanged.
  RecordingSession first;
  assert(gate.admit(&valid, DEC_2026, TEST_ANCHOR) && gate.admitted());
  assert(gate.write(first, request, length) == length && first.bytes == length && first.writes == 1);
  assert(gate.write(first, request, length) == length && first.bytes == 2 * length); // next batch, same session

  // Reconnect after the server closed the idle session: the new handshake serves an expired leaf.
  gate.reset();
  assert(!gate.admitted() && gate.write(first, request, length) == 0 && first.bytes == 2 * length);
  RecordingSession second;
  assert(!gate.admit(&expired, DEC_2026, TEST_ANCHOR));
  assert(gate.write(second, request, length) == 0 && second.writes == 0);

  // A failed check replaces an earlier admission even without reset.
  assert(gate.admit(&valid, DEC_2026, TEST_ANCHOR));
  assert(!gate.admit(&future, DEC_2026, TEST_ANCHOR) && gate.write(second, request, length) == 0 && !second.writes);
}

// Decodes the compiled-in PEM so the named constants cannot drift from the anchor itself.
static size_t decodePem(const char* pem, unsigned char* out, size_t cap) {
  const char* body = strstr(pem, "-----\n");
  assert(body);
  body += 6;
  unsigned value = 0, bits = 0;
  size_t used = 0;
  for (const char* c = body; *c && *c != '-'; c++) {
    const char* digits = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
    const char* at = strchr(digits, *c);
    if (*c == '\n' || *c == '=') continue;
    assert(at && *c);
    value = (value << 6) | static_cast<unsigned>(at - digits);
    bits += 6;
    if (bits >= 8) {
      bits -= 8;
      assert(used < cap);
      out[used++] = static_cast<unsigned char>(value >> bits);
      value &= (1u << bits) - 1;
    }
  }
  return used;
}

static int twoDigits(const unsigned char* p) { return (p[0] - '0') * 10 + (p[1] - '0'); }

static void testAnchorConstants() {
  unsigned char der[2048];
  const size_t length = decodePem(KiteWindTls::ISRG_ROOT_X1_PEM, der, sizeof(der));
  assert(length == 1391); // SEQUENCE header (4 bytes) plus 1387
  const unsigned char* subject = KiteWindTls::ISRG_ROOT_X1_SUBJECT;
  const size_t n = KiteWindTls::ISRG_ROOT_X1_SUBJECT_LENGTH;
  assert(n == 81 && subject[0] == 0x30 && subject[1] == n - 2);
  // Self-signed: issuer (offset 47) and subject (offset 160) both equal the constant.
  assert(!memcmp(der + 47, subject, n) && !memcmp(der + 160, subject, n));
  // Validity: SEQUENCE of two 13-byte UTCTimes; the second is notAfter.
  const unsigned char* validity = der + 128;
  assert(validity[0] == 0x30 && validity[1] == 0x1e && validity[17] == 0x17 && validity[18] == 0x0d && validity[31] == 'Z');
  const unsigned char* t = validity + 19;
  int year = twoDigits(t);
  Time notAfter = {year < 50 ? 2000 + year : 1900 + year, twoDigits(t + 2), twoDigits(t + 4), twoDigits(t + 6), twoDigits(t + 8), twoDigits(t + 10)};
  assert(epoch(notAfter) == KiteWindTls::ISRG_ROOT_X1_NOT_AFTER_UTC);
  static_assert(KiteWindTls::ISRG_ROOT_X1_NOT_AFTER_UTC == 2064567878, "2035-06-04T11:04:38Z");
}

// Automatic notice: fails once the compiled-in root ends within 18 months of the source date
// (SOURCE_DATE_EPOCH, as set by the release check) or of the time the test runs.
static int checkAnchorLifetime() {
  const int64_t margin = 548LL * 86400; // about 18 months
  const char* source = getenv("SOURCE_DATE_EPOCH");
  int64_t reference = static_cast<int64_t>(time(nullptr));
  if (source && *source) {
    // Strict: 1 to 10 digits within [2026-01-01, 2^32), so garbage cannot disable the guard.
    size_t digits = strspn(source, "0123456789");
    reference = digits && digits <= 10 && !source[digits] ? strtoll(source, nullptr, 10) : -1;
    if (reference < CLOCK_FLOOR_UTC || reference > static_cast<int64_t>(UINT32_MAX)) {
      fprintf(stderr, "SOURCE_DATE_EPOCH is not a plausible Unix time\n");
      return 1;
    }
  }
  if (KiteWindTls::ISRG_ROOT_X1_NOT_AFTER_UTC - reference < margin) {
    fprintf(stderr, "ISRG Root X1 ends within 18 months: add its successor to usermods/kite_wind/isrg_root_x1.h\n");
    return 1;
  }
  return 0;
}

int main() {
  testEpoch();
  testFloor();
  testDates();
  testChain();
  testIsrgChain();
  testGate();
  testAnchorConstants();
  if (checkAnchorLifetime()) return 1;
  printf("kite-wind-cert-test: all checks passed (floor %lld)\n", static_cast<long long>(MIN_VALID_UTC));
  return 0;
}
